--[[
    _Lyx_Fade.lua — engine for "Lyx_Create fade or crossfade to select items"
                    and "Lyx_Remove fade or crossfade to select items".

    Lane-safe:
      * neighbours are searched inside the same lane (fixed lanes: I_FIXEDLANE,
        free positioning: F_FREEMODE_Y), never "next item on the track".
      * razor areas pick items by their real on-screen Y (I_LASTY/I_LASTH vs the
        razor's top/bottom), so collapsed lanes / "show only playing lane" /
        free-mode tracks map correctly.
    Visible-only: items must be on screen vertically; without razor the edit
    point must also be inside the horizontal arrange view.
]]

local R = reaper
local M = {}
local CHART -- fade shape 7 DIR -> crossover offset table (assigned at bottom)

local function get(it, k) return R.GetMediaItemInfo_Value(it, k) end
local function set(it, k, v) R.SetMediaItemInfo_Value(it, k, v) end

local function bounds(it)
    local p, l = get(it, "D_POSITION"), get(it, "D_LENGTH")
    return p, p + l, l
end
M.bounds = bounds

local function within(x, a, b) return x >= a and x <= b end

---------------------------------------------------------------------------
-- Visibility
---------------------------------------------------------------------------
local arr_h
local function arrange_height()
    if not arr_h then
        local hwnd = R.JS_Window_FindChildByID and R.JS_Window_FindChildByID(R.GetMainHwnd(), 1000)
        if hwnd then arr_h = select(3, R.JS_Window_GetClientSize(hwnd)) end
        arr_h = arr_h or math.huge
    end
    return arr_h
end

function M.visible_y(it)
    local tr = R.GetMediaItem_Track(it)
    if not R.IsTrackVisible(tr, false) or get(it, "B_FIXEDLANE_HIDDEN") == 1 then return false end
    local y = R.GetMediaTrackInfo_Value(tr, "I_TCPY") + get(it, "I_LASTY")
    local h = get(it, "I_LASTH")
    return h > 0 and y + h > 0 and y < arrange_height()
end

function M.view() return R.BR_GetArrangeView(0) end

---------------------------------------------------------------------------
-- Lanes
---------------------------------------------------------------------------
local function lane_key(it)
    local mode = R.GetMediaTrackInfo_Value(R.GetMediaItem_Track(it), "I_FREEMODE")
    if mode == 2 then return get(it, "I_FIXEDLANE") end
    if mode == 1 then return string.format("%.4f", get(it, "F_FREEMODE_Y")) end
    return 0
end

-- per-track cache: lists[lane] = items in position order, where[item] = index
local cache = {}
local function lane_list(it)
    local tr = R.GetMediaItem_Track(it)
    local tc = cache[tr]
    if not tc then
        tc = { lists = {}, where = {} }
        for i = 0, R.CountTrackMediaItems(tr) - 1 do -- track items are position-sorted
            local x = R.GetTrackMediaItem(tr, i)
            local k = lane_key(x)
            local l = tc.lists[k] or {}
            tc.lists[k] = l
            l[#l + 1] = x
            tc.where[x] = #l
        end
        cache[tr] = tc
    end
    return tc.lists[lane_key(it)], tc.where[it]
end

-- dir = -1 previous, +1 next (same lane)
function M.neighbor(it, dir)
    local l, i = lane_list(it)
    return l and i and l[i + dir]
end

---------------------------------------------------------------------------
-- Razor areas
---------------------------------------------------------------------------
function M.razor_areas()
    local areas = {}
    for ti = 0, R.CountTracks(0) - 1 do
        local tr = R.GetTrack(0, ti)
        local _, str = R.GetSetMediaTrackInfo_String(tr, "P_RAZOREDITS_EXT", "", false)
        for a in str:gmatch("[^,]+") do
            local t = {}
            for w in a:gmatch("%S+") do t[#t + 1] = w end
            local s, e = tonumber(t[1]), tonumber(t[2])
            if s and e and (t[3] == nil or t[3] == '""') then -- skip envelope razors
                areas[#areas + 1] = { track = tr, s = s, e = e,
                                      top = tonumber(t[4]) or 0, bot = tonumber(t[5]) or 1 }
            end
        end
    end
    return areas
end

-- relative Y centre (0..1) of an item inside its track
local function item_center_y(it, tr, th)
    local h = get(it, "I_LASTH")
    if h > 0 and th > 0 then return (get(it, "I_LASTY") + h / 2) / th end
    if R.GetMediaTrackInfo_Value(tr, "I_FREEMODE") == 2 then -- fallback: equal lanes
        local n = math.max(1, R.GetMediaTrackInfo_Value(tr, "I_NUMFIXEDLANES"))
        return (get(it, "I_FIXEDLANE") + 0.5) / n
    end
    return 0.5
end

-- visible items of the area, grouped by lane (position order)
function M.area_lanes(a)
    local tr = a.track
    local th = R.GetMediaTrackInfo_Value(tr, "I_TCPH")
    local lanes, order, all = {}, {}, {}
    for i = 0, R.CountTrackMediaItems(tr) - 1 do
        local it = R.GetTrackMediaItem(tr, i)
        local p, e = bounds(it)
        if p < a.e and e > a.s and M.visible_y(it) then
            local cy = item_center_y(it, tr, th)
            if cy >= a.top and cy <= a.bot then
                local k = lane_key(it)
                if not lanes[k] then lanes[k] = {}; order[#order + 1] = k end
                table.insert(lanes[k], it)
                all[#all + 1] = it
            end
        end
    end
    local out = {}
    for _, k in ipairs(order) do out[#out + 1] = lanes[k] end
    return out, all
end

---------------------------------------------------------------------------
-- Fade shape 7 crossover math
---------------------------------------------------------------------------
local function dir_to_offset(dir)
    local i = math.floor((dir + 1) * 1000 + 0.5) + 1
    return CHART[math.max(1, math.min(#CHART, i))]
end

local function offset_to_dir(point)
    if point < -1 then return -1 elseif point > 1 then return 1 end
    local lo, hi = 1, #CHART -- largest i with CHART[i] <= point
    while lo < hi do
        local mid = (lo + hi + 1) // 2
        if CHART[mid] <= point then lo = mid else hi = mid - 1 end
    end
    return (lo - 1001) / 1000
end

-- where the two fade curves cross (time)
function M.crossover(a, b, a_end, b_pos)
    local in_len, out_len = get(b, "D_FADEINLEN_AUTO"), get(a, "D_FADEOUTLEN_AUTO")
    if in_len <= 0 or out_len <= 0 then return (a_end + b_pos) / 2 end
    local fin, fout = a_end - out_len, b_pos + in_len
    local center = (fin + fout) / 2
    if not (get(b, "C_FADEINSHAPE") == 7 and get(a, "C_FADEOUTSHAPE") == 7
            and get(a, "D_FADEOUTDIR") == get(b, "D_FADEINDIR")) then
        return center
    end
    return center + (fout - fin) / 2 * 0.85 * dir_to_offset(get(a, "D_FADEOUTDIR"))
end

-- shape 7 + DIR so the curves cross at `target`
function M.set_dir(a, b, target)
    set(a, "C_FADEOUTSHAPE", 7); set(b, "C_FADEINSHAPE", 7)
    local _, a_end = bounds(a)
    local b_pos = bounds(b)
    local fin  = a_end - get(a, "D_FADEOUTLEN_AUTO")
    local fout = b_pos + get(b, "D_FADEINLEN_AUTO")
    local half = (fout - fin) / 2 * 0.85
    local dir = (half > 0) and offset_to_dir((target - (fin + fout) / 2) / half) or 0
    set(a, "D_FADEOUTDIR", dir); set(b, "D_FADEINDIR", dir)
end

---------------------------------------------------------------------------
-- Primitive edits
---------------------------------------------------------------------------
function M.fade_in(it, len)  set(it, "D_FADEINLEN", len);  set(it, "D_FADEINLEN_AUTO", len)  end
function M.fade_out(it, len) set(it, "D_FADEOUTLEN", len); set(it, "D_FADEOUTLEN_AUTO", len) end
function M.clear_in(it)  set(it, "D_FADEINLEN", 0);  set(it, "D_FADEINLEN_AUTO", -1);  set(it, "D_FADEINDIR", 0)  end
function M.clear_out(it) set(it, "D_FADEOUTLEN", 0); set(it, "D_FADEOUTLEN_AUTO", -1); set(it, "D_FADEOUTDIR", 0) end
function M.max_in(it)  return math.max(get(it, "D_FADEINLEN"),  get(it, "D_FADEINLEN_AUTO"))  end
function M.max_out(it) return math.max(get(it, "D_FADEOUTLEN"), get(it, "D_FADEOUTLEN_AUTO")) end
function M.edges(it, s, e) R.BR_SetItemEdges(it, s, e) end

---------------------------------------------------------------------------
-- Helpers for both scripts
---------------------------------------------------------------------------
function M.selected_items()
    local t = {}
    for i = 0, R.CountSelectedMediaItems(0) - 1 do t[#t + 1] = R.GetSelectedMediaItem(0, i) end
    return t
end

-- run fn inside undo block + frozen UI
function M.wrap(name, fn)
    R.Undo_BeginBlock()
    R.PreventUIRefresh(1)
    fn()
    R.PreventUIRefresh(-1)
    R.UpdateArrange()
    R.Undo_EndBlock(name, -1)
end

